package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TextBuffer_contentsAsDecimal_TriageGen1Test {

    private BufferRecycler _recycler;
    private TextBuffer _textBuffer;

    @Before
    public void setUp() {
        _recycler = new BufferRecycler();
        _textBuffer = new TextBuffer(_recycler);
    }

    @Test
    public void testContentsAsDecimal_WithPreCutArray() throws Exception {
        // To trigger the first branch: if (_resultArray != null)
        // Since _resultArray is private, we simulate the state by using reflection 
        // or assuming the internal state is set via internal logic. 
        // However, in standard Jackson TextBuffer, _resultArray is set by internal parsing.
        // We will use reflection to force this state for branch coverage.
        java.lang.reflect.Field resultArrayField = TextBuffer.class.getDeclaredField("_resultArray");
        resultArrayField.setAccessible(true);
        byte[] mockArray = "123.45".getBytes();
        resultArrayField.set(_textBuffer, mockArray);

        BigDecimal expected = new BigDecimal("123.45");
        // Note: NumberInput.parseBigDecimal behavior depends on the byte content
        // We expect the method to call NumberInput.parseBigDecimal(_resultArray)
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }










}

package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
