import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TextBuffer_contentsAsDecimal_TriageGen1Test {

    private BufferRecycler _recycler;
    private TextBuffer _textBuffer;

    @Before
    public void setUp() {
        _recycler = new BufferRecycler();
        _textBuffer = new TextBuffer(_recycler);
    }



    @Test
    public void testContentsAsDecimal_WithSharedBuffer() throws Exception {
        // To trigger the second branch: if (_inputStart >= 0)
        // We use resetWithShared to set _inputBuffer, _inputStart, and _inputLen
        char[] sharedBuf = "456.78".toCharArray();
        _textBuffer.resetWithShared(sharedBuf, 0, sharedBuf.length);

        BigDecimal expected = new BigDecimal("456.78");
        assertEquals(expected, _textBuffer.contentsAsDecimal());
    }








}
